/* ===================== LỚP 2–5 · CHỦ ĐỀ 1 (ÔN TẬP VÀ BỔ SUNG) ===================== */
/* Đề viết lại theo kiến thức từng bài trong Vở BT-TH Toán 2–5 (KNTT): đổi bối cảnh, nhân vật, số liệu. */
import { fmt, pick, R, range } from '../../core/01-tien-ich.js';
import { ALLP1, P1BY } from './07-lop-9-chuong-i-phuong-trinh-va-he-hai-ph.js';
import { shuf } from '../../core/21-lop-6-che-do-tro-choi.js';
import { NUMW } from './24-lop-1-chu-de-1-cac-so-tu-0-den-10.js';
import { PRIM } from '../../core/25-lop-1-so-loi-sai-toan-jenny.js';
export function vnRead(n){if(n===0)return'không';const D=['không','một','hai','ba','bốn','năm','sáu','bảy','tám','chín'];
  const r3=(x,full)=>{const h=Math.floor(x/100),t=Math.floor(x/10)%10,u=x%10;let s=[];if(full||h)s.push(D[h]+' trăm');
    if(t===0){if(u&&(full||h))s.push('linh '+D[u]);else if(u)s.push(D[u])}else if(t===1){s.push('mười'+(u===0?'':u===5?' lăm':' '+D[u]))}else{s.push(D[t]+' mươi'+(u===0?'':u===1?' mốt':u===4?' tư':u===5?' lăm':' '+D[u]))}return s.join(' ')};
  const parts=[[1e9,'tỉ'],[1e6,'triệu'],[1e3,'nghìn'],[1,'']];let s=[],started=false;
  for(const[v,w]of parts){const c=Math.floor(n/v)%1000;if(c||(!started&&false)){s.push((r3(c,started)+(w?' '+w:'')).trim());started=true}else if(started&&v===1e3&&n%1e3){/* bỏ trống hàng nghìn */}}
  return s.join(' ').replace(/\s+/g,' ').trim()}
export const NQ=(q,say,a,sol,kind)=>({type:'num',q,say,a,sol,kind});
export function CQ(q,say,ans,cands,sol,kind,big){const s=[String(ans)];for(const c of cands){const v=String(c);if(s.length>=4)break;if(!s.includes(v))s.push(v)}const o=shuf(s);return{type:'opt',big:big?1:0,cols:o.length===4?2:3,q,say,opts:o.map(h=>({h,v:h})),a:o.indexOf(String(ans)),sol,kind}}
export const SG=(a,b,ta,tb,kind,va,vb)=>{va=va===undefined?a:va;vb=vb===undefined?b:vb;const ans=va>vb?0:va<vb?1:2;return{type:'opt',big:1,cols:3,q:`Chọn dấu đúng: <b>${ta} … ${tb}</b>`,say:'Em chọn dấu lớn hơn, bé hơn hay bằng.',opts:['&gt;','&lt;','='].map((h,v)=>({h,v})),a:ans,sol:`${ta} ${['&gt;','&lt;','='][ans]} ${tb}.`,kind}};
export const ORD=(vals,txt,kind)=>{const v=vals.map((x,i)=>[x,i]);return{type:'order',q:'Chạm các số theo thứ tự từ bé đến lớn.',say:'Em chạm vào các số theo thứ tự từ bé đến lớn nhé.',opts:vals.map(txt||String),a:[...v].sort((p,q)=>p[0]-q[0]).map(p=>p[1]),sol:`Từ bé đến lớn: ${[...vals].sort((x,y)=>x-y).map(txt||String).join(', ')}.`,kind}};
const NAMES=['Minh','Lan','Hà','Nam','An','Mai','Tú','Linh','Khôi','Vy'];
export const THINGS=[['quả cam','thùng'],['viên bi','hộp'],['cái bánh','khay'],['quyển vở','chồng'],['bông hoa','lẵng'],['chai nước','thùng'],['cái kẹo','túi']];
/* ---------- Lớp 2 ---------- */
const QL2={
 build:()=>()=>{const t=R(1,9),u=R(0,9),n=t*10+u;return NQ(`Số gồm <b>${t} chục</b> và <b>${u} đơn vị</b> là số nào?`,`Số gồm ${NUMW[t]} chục và ${NUMW[u]} đơn vị là số nào?`,n,`${t} chục và ${u} đơn vị là ${n}.`,'Cấu tạo số có hai chữ số')},
 read:()=>()=>{const n=R(11,99);return CQ(`Số <b>${vnRead(n)}</b> viết là:`,`Số ${vnRead(n)} viết là số nào?`,n,[n%10*10+Math.floor(n/10),n+10>99?n-10:n+10,n+1,n-1].filter(v=>v>=10&&v!==n),`${vnRead(n)} viết là ${n}.`,'Đọc, viết số đến 100',1)},
 cmp:()=>()=>{const a=R(10,99),b=Math.random()<.2?a:R(10,99);return SG(a,b,a,b,'So sánh số đến 100')},
 ord:()=>()=>ORD(shuf(range(10,99)).slice(0,4),null,'Xếp thứ tự số đến 100'),
 next:()=>()=>{const n=R(10,98),after=Math.random()<.5;const a=after?n+1:n-1;return NQ(`Số liền ${after?'sau':'trước'} của <b>${n}</b> là số nào?`,`Số liền ${after?'sau':'trước'} của ${vnRead(n)} là số nào?`,a,`Số liền ${after?'sau':'trước'} của ${n} là ${a}.`,'Số liền trước, số liền sau')},
 line:()=>()=>{const step=pick([1,10]),st=step===1?R(10,90):R(0,4)*10,arr=range(0,5).map(i=>st+i*step).filter(v=>v<=100).slice(0,6);while(arr.length<6)arr.unshift(arr[0]-step);const bl=shuf([1,2,3,4]).slice(0,2).sort((a,b)=>a-b),ans=bl.map(i=>arr[i]);const tiles=shuf([...ans,ans[0]+step*3,ans[1]-step*3].filter((v,i,s)=>v>=0&&s.indexOf(v)===i)).slice(0,4);
   if(!ans.every(v=>tiles.includes(v)))tiles.push(...ans.filter(v=>!tiles.includes(v)));return{type:'slots',q:`Điền số còn thiếu trên tia số (mỗi vạch cách nhau ${step}).`,say:`Mỗi vạch trên tia số cách nhau ${step===1?'một':'mười'}. Em kéo số còn thiếu vào ô trống.`,cells:arr.map((v,i)=>bl.includes(i)?null:v),tiles,a:ans,sol:`Dãy đúng: ${arr.join(', ')}.`,kind:'Tia số'}},
 partsAdd:()=>()=>{const a=R(10,60),b=R(10,99-a),s=a+b,k=R(0,2);return CQ(`Trong phép cộng <b>${a} + ${b} = ${s}</b>, số <b>${[a,b,s][k]}</b> gọi là gì?`,`Trong phép cộng ${a} cộng ${b} bằng ${s}, số ${[a,b,s][k]} gọi là gì?`,k<2?'Số hạng':'Tổng',['Số hạng','Tổng','Hiệu','Số trừ'],`${a} và ${b} là số hạng, ${s} là tổng.`,'Thành phần phép cộng')},
 partsSub:()=>()=>{const a=R(30,99),b=R(10,a-10),d=a-b,k=R(0,2);return CQ(`Trong phép trừ <b>${a} − ${b} = ${d}</b>, số <b>${[a,b,d][k]}</b> gọi là gì?`,`Trong phép trừ ${a} trừ ${b} bằng ${d}, số ${[a,b,d][k]} gọi là gì?`,['Số bị trừ','Số trừ','Hiệu'][k],['Số bị trừ','Số trừ','Hiệu','Tổng'],`${a} là số bị trừ, ${b} là số trừ, ${d} là hiệu.`,'Thành phần phép trừ')},
 sumOf:()=>()=>{const a1=R(1,6),b1=R(1,9-a1),a=a1*10+R(0,4),b=b1*10+R(0,5),s=a+b;return NQ(`Hai số hạng là <b>${a}</b> và <b>${b}</b>. Tổng là bao nhiêu?`,`Hai số hạng là ${a} và ${b}. Tổng bằng bao nhiêu?`,s,`${a} + ${b} = ${s}.`,'Tìm tổng')},
 diffOf:()=>()=>{const a=R(40,99),b=R(10,a-10);const bb=Math.floor(b/10)*10+Math.min(b%10,a%10);return NQ(`Số bị trừ là <b>${a}</b>, số trừ là <b>${bb}</b>. Hiệu là bao nhiêu?`,`Số bị trừ là ${a}, số trừ là ${bb}. Hiệu bằng bao nhiêu?`,a-bb,`${a} − ${bb} = ${a-bb}.`,'Tìm hiệu')},
 more:()=>()=>{const [p,q]=shuf(NAMES).slice(0,2),[th]=pick(THINGS);const a=R(25,95),b=R(10,a-5);const ask=Math.random()<.5;return NQ(ask?`${p} có ${a} ${th}, ${q} có ${b} ${th}. ${p} có nhiều hơn ${q} bao nhiêu ${th}?`:`${p} có ${a} ${th}, ${q} có ${b} ${th}. ${q} có ít hơn ${p} bao nhiêu ${th}?`,`${p} có ${a} ${th}, ${q} có ${b} ${th}. ${ask?p+' có nhiều hơn '+q:q+' có ít hơn '+p} bao nhiêu ${th}?`,a-b,`${a} − ${b} = ${a-b}.`,'Hơn, kém nhau bao nhiêu')},
 age:()=>()=>{const c=R(6,9),g=R(55,80);return NQ(`Bé ${pick(NAMES)} ${c} tuổi, bà ${g} tuổi. Bà hơn bé bao nhiêu tuổi?`,`Bé ${c} tuổi, bà ${g} tuổi. Bà hơn bé bao nhiêu tuổi?`,g-c,`${g} − ${c} = ${g-c}.`,'Hơn, kém nhau bao nhiêu')},
 add:()=>()=>{const t1=R(1,7),t2=R(1,9-t1),u1=R(0,8),u2=R(0,9-u1),a=t1*10+u1,b=t2*10+u2;return NQ(`<b>${a} + ${b} = ?</b>`,`${a} cộng ${b} bằng bao nhiêu?`,a+b,`${a} + ${b} = ${a+b}.`,'Cộng không nhớ trong phạm vi 100')},
 sub:()=>()=>{const t1=R(3,9),t2=R(1,t1-1),u1=R(2,9),u2=R(0,u1),a=t1*10+u1,b=t2*10+u2;return NQ(`<b>${a} − ${b} = ?</b>`,`${a} trừ ${b} bằng bao nhiêu?`,a-b,`${a} − ${b} = ${a-b}.`,'Trừ không nhớ trong phạm vi 100')},
 same:()=>()=>{const r=R(3,9)*10+R(0,9);const mk=ok=>{if(ok){const a=R(10,r-10);return`${a} + ${r-a}`}const v=r+pick([-10,-1,1,10,2]);const a=R(10,v-10);return Math.random()<.5?`${a} + ${v-a}`:`${v+12} − 12`};const good=mk(1);return CQ(`Phép tính nào có kết quả bằng <b>${r}</b>?`,`Phép tính nào có kết quả bằng ${r}?`,good,[mk(0),mk(0),mk(0),mk(0)],`${good} = ${r}.`,'Phép tính có cùng kết quả')},
};
/* ---------- Lớp 3 ---------- */
export const QL3={
 build:()=>()=>{const h=R(1,9),t=R(0,9),u=R(0,9),n=h*100+t*10+u;return NQ(`Số gồm <b>${h} trăm, ${t} chục và ${u} đơn vị</b> là số nào?`,`Số gồm ${NUMW[h]} trăm, ${NUMW[t]} chục và ${NUMW[u]} đơn vị là số nào?`,n,`${h} trăm, ${t} chục, ${u} đơn vị là ${n}.`,'Cấu tạo số có ba chữ số')},
 read:()=>()=>{const n=R(101,999);return CQ(`Số <b>${vnRead(n)}</b> viết là:`,`Số ${vnRead(n)} viết là số nào?`,n,[n+100>999?n-100:n+100,n+10>999?n-10:n+10,Number(String(n).split('').reverse().join(''))].filter(v=>v!==n&&v>99),`${vnRead(n)} viết là ${n}.`,'Đọc, viết số đến 1 000',1)},
 cmp:()=>()=>{const a=R(100,999),b=Math.random()<.4?Number(String(a).slice(0,2)+R(0,9)):R(100,999);return SG(a,b,a,b,'So sánh số đến 1 000')},
 mental:()=>()=>{const a=R(1,8)*100,b=R(1,9-a/100)*100,plus=Math.random()<.5;return plus?NQ(`<b>${a} + ${b} = ?</b>`,`${a} cộng ${b}?`,a+b,`${a/100} trăm + ${b/100} trăm = ${(a+b)/100} trăm.`,'Tính nhẩm số tròn trăm'):NQ(`<b>${a+b} − ${b} = ?</b>`,`${a+b} trừ ${b}?`,a,`${(a+b)/100} trăm − ${b/100} trăm = ${a/100} trăm.`,'Tính nhẩm số tròn trăm')},
 add:()=>()=>{const a=R(120,700),b=R(100,999-a);return NQ(`<b>${a} + ${b} = ?</b>`,`${a} cộng ${b} bằng bao nhiêu?`,a+b,`${a} + ${b} = ${a+b}.`,'Cộng trong phạm vi 1 000')},
 sub:()=>()=>{const a=R(300,999),b=R(100,a-50);return NQ(`<b>${a} − ${b} = ?</b>`,`${a} trừ ${b} bằng bao nhiêu?`,a-b,`${a} − ${b} = ${a-b}.`,'Trừ trong phạm vi 1 000')},
 findA:()=>()=>{const x=R(20,400),b=R(15,400),k=R(0,2);if(k===0)return NQ(`Tìm số trong ô: <b>☐ + ${b} = ${x+b}</b>`,`Số nào cộng ${b} bằng ${x+b}?`,x,`☐ = ${x+b} − ${b} = ${x}.`,'Tìm số hạng');if(k===1)return NQ(`Tìm số trong ô: <b>☐ − ${b} = ${x}</b>`,`Số nào trừ ${b} bằng ${x}?`,x+b,`☐ = ${x} + ${b} = ${x+b}.`,'Tìm số bị trừ');return NQ(`Tìm số trong ô: <b>${x+b} − ☐ = ${x}</b>`,`${x+b} trừ số nào bằng ${x}?`,b,`☐ = ${x+b} − ${x} = ${b}.`,'Tìm số trừ')},
 robot:()=>()=>{const x=R(10,90),b=R(10,90);return NQ(`Rô-bốt nghĩ một số. Lấy số đó cộng ${b} thì được ${x+b}. Rô-bốt nghĩ số nào?`,`Rô bốt nghĩ một số. Lấy số đó cộng ${b} thì được ${x+b}. Rô bốt nghĩ số nào?`,x,`${x+b} − ${b} = ${x}.`,'Tìm số hạng')},
 mul:(ks)=>()=>{const k=pick(ks),n=R(1,10),div=Math.random()<.45;return div?NQ(`<b>${k*n} : ${k} = ?</b>`,`${k*n} chia ${k} bằng bao nhiêu?`,n,`Vì ${k} × ${n} = ${k*n} nên ${k*n} : ${k} = ${n}.`,`Bảng chia ${ks.join(', ')}`):NQ(`<b>${k} × ${n} = ?</b>`,`${k} nhân ${n} bằng bao nhiêu?`,k*n,`${k} × ${n} = ${k*n}.`,`Bảng nhân ${ks.join(', ')}`)},
 mulWord:(ks)=>()=>{const k=pick(ks),n=R(2,9),[th,box]=pick(THINGS),div=Math.random()<.5;return div?NQ(`Có ${k*n} ${th} xếp đều vào ${k} ${box}. Mỗi ${box} có mấy ${th}?`,`Có ${k*n} ${th} xếp đều vào ${k} ${box}. Mỗi ${box} có mấy ${th}?`,n,`${k*n} : ${k} = ${n}.`,`Toán lời văn bảng ${ks.join(', ')}`):NQ(`Mỗi ${box} có ${k} ${th}. ${n} ${box} như thế có bao nhiêu ${th}?`,`Mỗi ${box} có ${k} ${th}. ${n} ${box} có bao nhiêu ${th}?`,k*n,`${k} × ${n} = ${k*n}.`,`Toán lời văn bảng ${ks.join(', ')}`)},
 group:()=>()=>{const k=pick([2,3,4,5]),n=R(3,9);return NQ(`Lớp có ${k*n} bạn chia đều thành các nhóm, mỗi nhóm ${k} bạn. Có mấy nhóm?`,`Lớp có ${k*n} bạn, mỗi nhóm ${k} bạn. Có mấy nhóm?`,n,`${k*n} : ${k} = ${n}.`,'Chia thành nhóm')},
 least:(ks)=>()=>{const ex=shuf(range(0,30)).map(()=>{const k=pick(ks),n=R(2,10);return[`${k} × ${n}`,k*n]});const u=[];ex.forEach(e=>{if(u.length<4&&!u.some(x=>x[1]===e[1]))u.push(e)});const m=u.reduce((a,b)=>b[1]<a[1]?b:a);return CQ('Phép tính nào có kết quả <b>bé nhất</b>?','Phép tính nào có kết quả bé nhất?',m[0],u.filter(x=>x!==m).map(x=>x[0]),u.map(x=>`${x[0]} = ${x[1]}`).join('; ')+'.','So sánh kết quả phép nhân')},
 unit:()=>()=>{const c=pick([['1 m','cm',100],['1 m','dm',10],['1 dm','cm',10],['1 km','m',1000]]);const k=R(2,9);const s=c[0].replace('1 ',k+' ');return NQ(`<b>${s} = ? ${c[1]}</b>`,`${s.replace('m',' mét').replace('dm','đề xi mét')} bằng bao nhiêu ${c[1]}?`,k*c[2],`${c[0]} = ${c[2]} ${c[1]} nên ${s} = ${k*c[2]} ${c[1]}.`,'Đổi đơn vị độ dài')},
 zigzag:()=>()=>{const n=pick([3,4]),seg=range(1,n).map(()=>R(5,25));const L='ABCDE';return NQ(`Đường gấp khúc ${L.slice(0,n+1)} có các đoạn dài ${seg.join(' cm, ')} cm. Đường gấp khúc dài bao nhiêu xăng-ti-mét?`,`Đường gấp khúc có các đoạn dài ${seg.join(', ')} xăng ti mét. Dài tất cả bao nhiêu?`,seg.reduce((a,b)=>a+b,0),`${seg.join(' + ')} = ${seg.reduce((a,b)=>a+b,0)} (cm).`,'Độ dài đường gấp khúc')},
};
/* ---------- Lớp 4 ---------- */
const sp=n=>fmt(n);
const QL4={
 build:()=>()=>{const d=[R(1,9),R(0,9),R(0,9),R(0,9),R(0,9)],n=Number(d.join(''));return NQ(`Số gồm <b>${d[0]} chục nghìn, ${d[1]} nghìn, ${d[2]} trăm, ${d[3]} chục và ${d[4]} đơn vị</b> là số nào?`,`Số gồm ${NUMW[d[0]]} chục nghìn, ${NUMW[d[1]]} nghìn, ${NUMW[d[2]]} trăm, ${NUMW[d[3]]} chục và ${NUMW[d[4]]} đơn vị là số nào?`,n,`Số đó là ${sp(n)}.`,'Cấu tạo số có năm chữ số')},
 expand:()=>()=>{const n=R(10001,99999),s=String(n),k=R(1,3),place=10**(4-k),v=Number(s[k])*place||place;const n2=n-Number(s[k])*place+v;const parts=String(n2).split('').map((c,i)=>Number(c)*10**(4-i)).filter(Boolean);const miss=parts.indexOf(v);return NQ(`<b>${sp(n2)} = ${parts.map((p,i)=>i===miss?'☐':sp(p)).join(' + ')}</b>`,`Viết ${sp(n2)} thành tổng. Số còn thiếu trong ô là số nào?`,v,`${sp(n2)} = ${parts.map(sp).join(' + ')}.`,'Viết số thành tổng')},
 read:()=>()=>{const n=R(10001,99999);return CQ(`Số <b>${vnRead(n)}</b> viết là:`,`Số ${vnRead(n)} viết là số nào?`,sp(n),[sp(n+1000>99999?n-1000:n+1000),sp(n+10>99999?n-10:n+10),sp(Number(String(n).slice(0,2)+'0'+String(n).slice(3)))].filter(v=>v!==sp(n)),`${vnRead(n)}: ${sp(n)}.`,'Đọc, viết số đến 100 000',1)},
 cmp:()=>()=>{const a=R(10000,99999),b=Math.random()<.5?a+pick([-1,1])*R(1,9)*pick([1,10,100]):R(10000,99999);return SG(a,b,sp(a),sp(b),'So sánh số đến 100 000',a,b)},
 mental:()=>()=>{const a=R(1,7)*10000,b=R(1,9-a/10000)*10000,k=R(0,2);if(k===0)return NQ(`<b>${sp(a)} + ${sp(b)} = ?</b>`,`${a} cộng ${b}?`,a+b,`${a/1e4} chục nghìn + ${b/1e4} chục nghìn = ${(a+b)/1e4} chục nghìn.`,'Tính nhẩm');if(k===1)return NQ(`<b>${sp(a+b)} − ${sp(b)} = ?</b>`,`${a+b} trừ ${b}?`,a,`= ${sp(a)}.`,'Tính nhẩm');const m=R(2,4),c=R(1,3)*10000;return NQ(`<b>${sp(c)} × ${m} = ?</b>`,`${c} nhân ${m}?`,c*m,`= ${sp(c*m)}.`,'Tính nhẩm')},
 add:()=>()=>{const a=R(10000,60000),b=R(1000,99999-a);return NQ(`<b>${sp(a)} + ${sp(b)} = ?</b>`,`${a} cộng ${b} bằng bao nhiêu?`,a+b,`= ${sp(a+b)}.`,'Cộng trong phạm vi 100 000')},
 sub:()=>()=>{const a=R(30000,99999),b=R(1000,a-1000);return NQ(`<b>${sp(a)} − ${sp(b)} = ?</b>`,`${a} trừ ${b} bằng bao nhiêu?`,a-b,`= ${sp(a-b)}.`,'Trừ trong phạm vi 100 000')},
 mul1:()=>()=>{const m=R(2,6),a=R(1000,Math.floor(99999/m));return NQ(`<b>${sp(a)} × ${m} = ?</b>`,`${a} nhân ${m} bằng bao nhiêu?`,a*m,`= ${sp(a*m)}.`,'Nhân với số có một chữ số')},
 div1:()=>()=>{const m=R(2,9),q=R(1000,Math.floor(99999/m));return NQ(`<b>${sp(q*m)} : ${m} = ?</b>`,`${q*m} chia ${m} bằng bao nhiêu?`,q,`Vì ${sp(q)} × ${m} = ${sp(q*m)}.`,'Chia cho số có một chữ số')},
 even:()=>()=>{const tiles=shuf(range(0,40).map(()=>R(100,9999))).slice(0,6);if(!tiles.some(v=>v%2===0))tiles[0]++;if(tiles.every(v=>v%2===0))tiles[1]++;return{type:'pick',q:'Chạm vào <b>tất cả</b> các số chẵn.',say:'Chạm vào tất cả các số chẵn, rồi bấm kiểm tra.',opts:tiles.map(sp),a:tiles.map((v,i)=>v%2===0?i:-1).filter(i=>i>=0),sol:'Số chẵn có chữ số tận cùng là 0, 2, 4, 6, 8.',kind:'Số chẵn, số lẻ'}},
 evenNext:()=>()=>{const n=R(100,9999),odd=Math.random()<.5;let a=n+1;while((a%2===1)!==odd)a++;return NQ(`Số <b>${odd?'lẻ':'chẵn'}</b> liền sau số <b>${sp(n)}</b> là số nào?`,`Số ${odd?'lẻ':'chẵn'} liền sau ${n} là số nào?`,a,`Sau ${sp(n)}, số ${odd?'lẻ':'chẵn'} gần nhất là ${sp(a)}.`,'Số chẵn, số lẻ')},
 expr:()=>()=>{const a=R(2,15),k=R(0,2);if(k===0){const c=R(3,9),b=R(a*c,200);return NQ(`Với <b>a = ${a}</b>, giá trị của biểu thức <b>${b} − a × ${c}</b> là:`,`Với a bằng ${a}, tính ${b} trừ a nhân ${c}.`,b-a*c,`${b} − ${a} × ${c} = ${b} − ${a*c} = ${b-a*c}.`,'Biểu thức chứa chữ')}if(k===1){const c=R(10,90),d=R(2,5);return NQ(`Với <b>a = ${a}</b>, giá trị của biểu thức <b>(a + ${c}) × ${d}</b> là:`,`Với a bằng ${a}, tính a cộng ${c}, rồi nhân ${d}.`,(a+c)*d,`(${a} + ${c}) × ${d} = ${a+c} × ${d} = ${(a+c)*d}.`,'Biểu thức chứa chữ')}const b=R(2,9),c=R(2,9);return NQ(`Với <b>m = ${a}, n = ${b}, p = ${c}</b>, tính <b>m + n × p</b>.`,`Với m bằng ${a}, n bằng ${b}, p bằng ${c}, tính m cộng n nhân p.`,a+b*c,`${a} + ${b} × ${c} = ${a} + ${b*c} = ${a+b*c}.`,'Biểu thức chứa chữ')},
 step3:()=>()=>{const [th,box]=pick(THINGS),k=R(3,6),n=R(12,30),sold=R(5,k*n-10),add=R(5,30);return NQ(`Cửa hàng có ${k} ${box}, mỗi ${box} ${n} ${th}. Buổi sáng bán ${sold} ${th}, buổi chiều nhập thêm ${add} ${th}. Cửa hàng có bao nhiêu ${th}?`,`Có ${k} ${box}, mỗi ${box} ${n} ${th}. Bán ${sold}, rồi nhập thêm ${add}. Còn bao nhiêu?`,k*n-sold+add,`${k} × ${n} = ${k*n}; ${k*n} − ${sold} = ${k*n-sold}; ${k*n-sold} + ${add} = ${k*n-sold+add}.`,'Bài toán ba bước tính')},
 zig:()=>()=>{const a=R(10,30),c=R(10,40);return NQ(`Đường gấp khúc MNPQ có MN = ${a} cm, NP dài gấp đôi MN, PQ = ${c} cm. Đường gấp khúc dài bao nhiêu xăng-ti-mét?`,`MN dài ${a}, NP gấp đôi MN, PQ dài ${c} xăng ti mét. Đường gấp khúc dài bao nhiêu?`,a+2*a+c,`NP = ${2*a} cm; ${a} + ${2*a} + ${c} = ${3*a+c} (cm).`,'Bài toán ba bước tính')},
};
/* ---------- Lớp 5 ---------- */
const gcd=(a,b)=>b?gcd(b,a%b):a;
export const F=(n,d)=>`<span class="frac"><span>${n}</span><span>${d}</span></span>`;
const FS=(n,d)=>{const g=gcd(n,d);return[n/g,d/g]};
const QL5={
 place:()=>()=>{const n=R(1000000,9999999),str=String(n);let k;do{k=R(0,5)}while(str[k]==='0');const dg=str[k],v=Number(dg)*10**(6-k);let html='',c=0;sp(n).split('').forEach(ch=>{if(/\d/.test(ch)){html+=c===k?`<u class="hl">${ch}</u>`:ch;c++}else html+=ch});const cands=[v*10,v/10,v*100,Number(dg)].filter(x=>x!==v&&x>=1&&Number.isInteger(x));return CQ(`Giá trị của chữ số được gạch chân trong số <b>${html}</b> là:`,`Giá trị của chữ số ${dg} được gạch chân trong số này là bao nhiêu?`,sp(v),cands.map(sp),`Chữ số ${dg} đứng ở hàng có giá trị ${sp(v)}.`,'Giá trị của chữ số')},
 read:()=>()=>{const n=R(1,9)*1e6+R(0,999)*1e3+R(0,999);return CQ(`Số <b>${vnRead(n)}</b> viết là:`,`Số ${vnRead(n)} viết là số nào?`,sp(n),[sp(n+1e6>9999999?n-1e6:n+1e6),sp(n-(n%1000)+((n%1000+100)%1000)),sp(Math.floor(n/10))].filter(v=>v!==sp(n)),`${vnRead(n)}: ${sp(n)}.`,'Đọc, viết số tự nhiên',1)},
 calc:()=>()=>{const k=R(0,3);if(k===0){const a=R(1000,60000),b=R(1000,30000);return NQ(`<b>${sp(a)} + ${sp(b)} = ?</b>`,`${a} cộng ${b}?`,a+b,`= ${sp(a+b)}.`,'Phép tính với số tự nhiên')}if(k===1){const a=R(20000,90000),b=R(1000,a-1000);return NQ(`<b>${sp(a)} − ${sp(b)} = ?</b>`,`${a} trừ ${b}?`,a-b,`= ${sp(a-b)}.`,'Phép tính với số tự nhiên')}if(k===2){const a=R(105,999),b=R(12,48);return NQ(`<b>${a} × ${b} = ?</b>`,`${a} nhân ${b}?`,a*b,`= ${sp(a*b)}.`,'Phép tính với số tự nhiên')}const b=R(12,45),q=R(25,250);return NQ(`<b>${sp(b*q)} : ${b} = ?</b>`,`${b*q} chia ${b}?`,q,`Vì ${q} × ${b} = ${sp(b*q)}.`,'Phép tính với số tự nhiên')},
 mental:()=>()=>{const c=pick([[25,4],[125,8],[50,2],[250,4]]),m=R(2,9)*pick([1,10]);return NQ(`Tính nhẩm: <b>${c[0]} × ${m} × ${c[1]} = ?</b>`,`Tính nhẩm ${c[0]} nhân ${m} nhân ${c[1]}.`,c[0]*c[1]*m,`${c[0]} × ${c[1]} = ${c[0]*c[1]}, nhân ${m} được ${sp(c[0]*c[1]*m)}.`,'Tính nhẩm')},
 fracEq:()=>()=>{const d=R(2,9),n=R(1,d-1),[a,b]=FS(n,d),k=R(2,5);const good=`${a*k}/${b*k}`;const bads=[`${a*k}/${b*k+1}`,`${a+k}/${b+k}`,`${a*k+1}/${b*k}`,`${b}/${a}`];const o=CQ(`Phân số nào bằng phân số ${F(a,b)}?`,`Phân số nào bằng phân số ${a} phần ${b}?`,good,bads.filter(x=>x!==good),`${F(a,b)} = ${F(a*k,b*k)} (nhân cả tử và mẫu với ${k}).`,'Phân số bằng nhau');o.opts=o.opts.map(x=>({...x,h:F(...x.h.split('/'))}));return o},
 simp:()=>()=>{const b=R(2,9),a=R(1,b-1),[p,q]=FS(a,b),k=R(2,6);const good=`${p}/${q}`;const o=CQ(`Rút gọn phân số ${F(p*k,q*k)} được:`,`Rút gọn phân số ${p*k} phần ${q*k}.`,good,[`${p*k/ (k>2?2:1)}/${q*k/(k>2?2:1)}`,`${q}/${p}`,`${p+1}/${q}`,`${p}/${q+1}`].filter(x=>x!==good),`Chia cả tử và mẫu cho ${k}: ${F(p,q)}.`,'Rút gọn phân số');o.opts=o.opts.map(x=>({...x,h:F(...x.h.split('/'))}));return o},
 fcmp:()=>()=>{const d=R(3,12),same=Math.random()<.5;let a,b,c,e;if(same){a=R(1,d-1);b=R(1,d-1);c=d;e=d}else{a=R(1,8);b=a;c=R(2,12);e=R(2,12)}return SG(0,0,F(a,c),F(b,e),'So sánh phân số',a/c,b/e)},
 decfr:()=>()=>{const good=pick(['7/10','9/100','13/100','3/1000','27/10']);const bads=shuf(['3/5','7/20','9/25','1/4','11/30','4/9']).slice(0,3);const o=CQ('Phân số nào là <b>phân số thập phân</b>?','Phân số nào là phân số thập phân?',good,bads,'Phân số thập phân có mẫu số là 10, 100, 1 000, …','Phân số thập phân');o.opts=o.opts.map(x=>({...x,h:F(...x.h.split('/'))}));return o},
 toDec:()=>()=>{const c=pick([[1,2,10],[3,5,10],[2,5,10],[1,4,100],[3,4,100],[7,20,100],[9,25,100],[1,5,10],[4,5,10],[11,50,100]]);return NQ(`Viết thành phân số thập phân: ${F(c[0],c[1])} = ${F('☐',c[2])}`,`${c[0]} phần ${c[1]} bằng mấy phần ${c[2]}?`,c[0]*c[2]/c[1],`${F(c[0],c[1])} = ${F(c[0]*c[2]/c[1],c[2])}.`,'Phân số thập phân')},
 fadd:()=>()=>{const pairs=[[2,3],[2,4],[3,4],[2,5],[3,6],[4,6],[2,6],[3,5]];const [d1,d2]=pick(pairs),a=R(1,d1-1),b=R(1,d2-1),plus=Math.random()<.6||a/d1<=b/d2;let n=plus?a*d2+b*d1:a*d2-b*d1,dd=d1*d2;const [p,q]=FS(n,dd);const good=`${p}/${q}`;const o=CQ(`${F(a,d1)} ${plus?'+':'−'} ${F(b,d2)} = ?`,`${a} phần ${d1} ${plus?'cộng':'trừ'} ${b} phần ${d2} bằng bao nhiêu?`,good,[`${a+(plus?b:-b)}/${d1+d2}`,`${p+1}/${q}`,`${p}/${q+1}`,`${n}/${d1+d2}`].filter(x=>x!==good&&!x.startsWith('0/')&&!x.startsWith('-')),`Quy đồng mẫu số rồi ${plus?'cộng':'trừ'}: kết quả ${F(p,q)}.`,'Cộng, trừ phân số khác mẫu');o.opts=o.opts.map(x=>({...x,h:F(...x.h.split('/'))}));return o},
 fmul:()=>()=>{const a=R(1,5),b=R(a+1,9),c=R(1,5),d=R(c+1,9),[p,q]=FS(a*c,b*d),div=Math.random()<.4;let pp=p,qq=q;if(div){[pp,qq]=FS(a*d,b*c)}const good=`${pp}/${qq}`;const o=CQ(`${F(a,b)} ${div?':':'×'} ${F(c,d)} = ?`,`${a} phần ${b} ${div?'chia':'nhân'} ${c} phần ${d} bằng bao nhiêu?`,good,[`${a*c}/${b+d}`,`${pp+1}/${qq}`,`${qq}/${pp}`,`${a+c}/${b+d}`].filter(x=>x!==good),div?`Nhân với phân số đảo ngược: ${F(pp,qq)}.`:`Tử nhân tử, mẫu nhân mẫu: ${F(pp,qq)}.`,'Nhân, chia phân số');o.opts=o.opts.map(x=>({...x,h:F(...x.h.split('/'))}));return o},
 mixed:()=>()=>{const w=R(1,5),d=R(2,9),n=R(1,d-1);const good=`${w*d+n}/${d}`;const o=CQ(`Hỗn số <b>${w}</b>${F(n,d)} viết thành phân số là:`,`Hỗn số ${w} và ${n} phần ${d} viết thành phân số là gì?`,good,[`${w+n}/${d}`,`${w*n+d}/${d}`,`${w*d+n}/${n}`,`${w*d}/${d}`].filter(x=>x!==good),`${w} × ${d} + ${n} = ${w*d+n}, nên ${F(w*d+n,d)}.`,'Hỗn số');o.opts=o.opts.map(x=>({...x,h:F(...x.h.split('/'))}));return o},
 mixRead:()=>()=>{const w=R(1,9),d=R(2,9),n=R(1,d-1);const good=`${w}|${n}/${d}`;const opts=shuf([good,`${n}|${w}/${d}`,`${w}|${d}/${n}`,`${d}|${n}/${w}`].filter((v,i,s)=>s.indexOf(v)===i));return{type:'opt',cols:2,q:`<b>${NUMW[w]} và ${NUMW[n]} phần ${NUMW[d]}</b> viết là:`,say:`${NUMW[w]} và ${NUMW[n]} phần ${NUMW[d]} viết là hỗn số nào?`,opts:opts.map(v=>{const [a,f]=v.split('|'),[x,y]=f.split('/');return{h:`<span class="mix"><b>${a}</b>${F(x,y)}</span>`,v}}),a:opts.indexOf(good),sol:`Phần nguyên ${w}, phần phân số ${F(n,d)}.`,kind:'Đọc, viết hỗn số'}},
 unit:()=>()=>{const c=pick([['m','cm',100],['kg','g',1000],['km','m',1000],['m²','dm²',100],['giờ','phút',60]]);const a=R(1,9),b=R(1,c[2]-1);return NQ(`<b>${a} ${c[0]} ${b} ${c[1]} = ? ${c[1]}</b>`,`${a} ${c[0]} ${b} ${c[1]} bằng bao nhiêu ${c[1]}?`,a*c[2]+b,`${a} ${c[0]} = ${a*c[2]} ${c[1]}; ${a*c[2]} + ${b} = ${a*c[2]+b}.`,'Đổi đơn vị đo')},
 rectA:()=>()=>{const a=R(5,30),b=R(3,a);const per=Math.random()<.5;return NQ(`Hình chữ nhật dài ${a} cm, rộng ${b} cm. ${per?'Chu vi':'Diện tích'} là bao nhiêu ${per?'cm':'cm²'}?`,`Hình chữ nhật dài ${a}, rộng ${b} xăng ti mét. Tính ${per?'chu vi':'diện tích'}.`,per?2*(a+b):a*b,per?`(${a} + ${b}) × 2 = ${2*(a+b)} (cm).`:`${a} × ${b} = ${a*b} (cm²).`,'Chu vi, diện tích')},
 tank:()=>()=>{const d=pick([4,5,6,8]),a=R(1,d-2),b=R(1,d-a-1);const [p,q]=FS(a+b,d);const good=`${p}/${q}`;const o=CQ(`Giờ đầu vòi nước chảy được ${F(a,d)} bể, giờ thứ hai chảy được ${F(b,d)} bể. Cả hai giờ chảy được mấy phần bể?`,`Giờ đầu chảy ${a} phần ${d} bể, giờ sau chảy ${b} phần ${d} bể. Cả hai giờ chảy được mấy phần bể?`,good,[`${a+b}/${2*d}`,`${a*b}/${d}`,`${p}/${q+1}`].filter(x=>x!==good),`${F(a,d)} + ${F(b,d)} = ${F(p,q)} (bể).`,'Toán lời văn phân số');o.opts=o.opts.map(x=>({...x,h:F(...x.h.split('/'))}));return o},
};
